import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Weitere Optionen","description":"Weitere UIX-Styling-Funktionen und Randfälle.","frontmatter":{"title":"Weitere Optionen","description":"Weitere UIX-Styling-Funktionen und Randfälle."},"headers":[],"relativePath":"projects/uix/using/other.md","filePath":"projects/uix/using/other.md","lastUpdated":1792861021000}'),a={name:"projects/uix/using/other.md"};function o(d,e,l,s,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="weitere-styling-optionen" tabindex="-1">Weitere Styling-Optionen <a class="header-anchor" href="#weitere-styling-optionen" aria-label="Permalink to &quot;Weitere Styling-Optionen&quot;">​</a></h1><p>Diese Seite sammelt kleinere Styling-Funktionen und Randfälle, die nicht in die anderen UIX-Styling-Kategorien passen.</p><p>UIX kann neben Karten, Rows, Badges, Bildern und Views auch andere Home-Assistant-Frontend-Bereiche über passende Theme-Variablen erreichen. Dazu gehören zum Beispiel Dialoge, Toasts, Sidebars, Konfigurationsseiten, Kalender, To-do-Ansichten, History-Ansichten und Persistent Notifications.</p><p>Wichtig ist immer, das DOM-Ziel zu prüfen und den passenden UIX-Kontext zu wählen:</p><ul><li>Für lokale Kartenänderungen: <code>uix:</code> direkt in der Karte.</li><li>Für wiederverwendbare globale Regeln: UIX-Theme-Variablen wie <code>uix-card</code>, <code>uix-row</code>, <code>uix-dialog</code> oder <code>uix-config</code>.</li><li>Für Shadow-DOM-Pfade: die jeweilige <code>-yaml</code>-Variante.</li><li>Für dynamische Werte: Jinja2-Templates, Makros oder Billets.</li></ul><p>Wenn ein Element nicht zuverlässig gefunden wird, prüfe zuerst <a href="./../concepts/dom">DOM-Navigation</a>, Lade-Reihenfolge und mögliche Shadow-Root-Grenzen.</p><h2 id="haufige-zielbereiche" tabindex="-1">Häufige Zielbereiche <a class="header-anchor" href="#haufige-zielbereiche" aria-label="Permalink to &quot;Häufige Zielbereiche&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Möglicher UIX-Kontext</th></tr></thead><tbody><tr><td>Dialoge</td><td><code>uix-dialog</code> oder passende Dialog-spezifische Regeln</td></tr><tr><td>Konfigurationsseiten</td><td><code>uix-config</code></td></tr><tr><td>Sidebar</td><td>Theme- oder Panel-Kontext</td></tr><tr><td>Toasts und Hinweise</td><td>passender Frontend-Kontext, abhängig vom DOM</td></tr><tr><td>Kalender und To-do</td><td>Karten- oder Panel-Kontext</td></tr></tbody></table><p>Nicht jeder Home-Assistant-Bereich ist gleich stabil. Prüfe daher bei Randfällen immer mit den DOM-Helfern, ob UIX den gewünschten Bereich tatsächlich erreicht.</p><h2 id="vorgehen-bei-unbekannten-elementen" tabindex="-1">Vorgehen bei unbekannten Elementen <a class="header-anchor" href="#vorgehen-bei-unbekannten-elementen" aria-label="Permalink to &quot;Vorgehen bei unbekannten Elementen&quot;">​</a></h2><ol><li>Element im Browser-Inspektor auswählen.</li><li><code>uix_tree($0)</code> oder <code>uix_style_path($0)</code> in der Konsole ausführen.</li><li>Den vorgeschlagenen Pfad in einer kleinen Testregel verwenden.</li><li>Erst danach komplexes Styling ergänzen.</li></ol>',11)])])}const p=n(a,[["render",o]]);export{g as __pageData,p as default};
